<script setup lang="ts">
import InventoryThresholds from '~/components/reports/InventoryThresholds.vue'
import InventoryComposition from '~/components/reports/InventoryComposition.vue'
import InventoryCapacity from '~/components/reports/InventoryCapacity.vue'
import InventoryAbc from '~/components/reports/InventoryAbc.vue'
import InventoryExpiry from '~/components/reports/InventoryExpiry.vue'
import InventoryAge from '~/components/reports/InventoryAge.vue'
const {t}=useI18n(),route=useRoute(),router=useRouter(),warehouses=useWarehouseStore(),{bizErrorMessage}=useBizError()
const {$dayjs}=useNuxtApp()
const staff=useStaffStore(),ready=ref(false)
const data=ref<any>(null),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||''))
const warehouseId=computed(()=>warehouses.currentWarehouse?.id||null)
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]==='')delete query[key];router.push({query})}
let generation=0
const load=async()=>{const seq=++generation;data.value=null;error.value='';loading.value=false;if(!warehouseId.value)return;loading.value=true;ready.value=false;const current=await staff.getCurrentStaffInfo();if(seq!==generation)return;if(!current){error.value=t('common.validation.company-required');loading.value=false;return}ready.value=true;const result=await httpRequest<any>('/api/warehouse/inventory/metrics',{params:{...route.query,warehouse_id:warehouseId.value,per_page:50},headers:warehouseHeaders(warehouseId.value),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
const exporting=ref(false)
const download=async(format:'csv'|'xlsx')=>{
 if(exporting.value||loading.value||!ready.value||!warehouseId.value||!data.value)return
 exporting.value=true
 try{
  const params=new URLSearchParams(Object.entries({...route.query,format,date:data.value.metric_date}).filter(([key,value])=>!['page','per_page'].includes(key)&&value!=null&&value!=='').map(([key,value])=>[key,String(value)]))
  await downloadFile('/api/warehouse/inventory/metrics/export?'+params,{headers:warehouseHeaders(warehouseId.value)},'inventory-metrics.'+format)
 }catch(e){error.value=bizErrorMessage(e as HttpRequestError)}finally{exporting.value=false}
}
const productScope=computed(()=>Object.fromEntries(['category','brand','category_missing','brand_missing'].filter(key=>route.query[key]!=null).map(key=>[key,route.query[key]])))
const summary=computed(()=>data.value?.summary)
const buckets=computed(()=>[{key:'age_0_30',label:'0–30',color:'#BFB9FE'},{key:'age_31_90',label:'31–90',color:'#9B8AFB'},{key:'age_91_180',label:'91–180',color:'#7855FE'},{key:'age_over_180',label:'180+',color:'#4E1DBC'},{key:'unknown',label:t('inventory-analysis.unknown'),color:'#CDD1DA'}].map(row=>({...row,value:summary.value?.age_buckets?.[row.key]||0})))
const sortOptions=computed(()=>['out_qty_30d','out_qty_90d','weighted_age_days','turnover_days_30d','total_stock'].map((value,index)=>({value,label:t(['inventory-analysis.out30','inventory-analysis.out90','inventory-analysis.average-age','inventory-analysis.turnover','goods.ui.onhand'][index]!)})))
const columns=computed(()=>[{key:'goods',label:t('nav.goods'),wrap:true},...['total_stock','out_qty_30d','out_qty_90d','weighted_age_days','turnover_days_30d','days_of_supply'].map((key,index)=>({key,label:t(['goods.ui.onhand','inventory-analysis.out30','inventory-analysis.out90','inventory-analysis.average-age','inventory-analysis.turnover','inventory-analysis.supply'][index]!),type:'qty' as const,keepZero:true})),{key:'last_out_at',label:t('inventory-analysis.last-out'),value:(row:any)=>row.last_out_at?$dayjs(row.last_out_at,'YYYY-MM-DD',warehouses.currentWarehouse):'—'},{key:'abc_class',label:'ABC'},{key:'status',label:t('common.fields.status')}])
watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(warehouseId,()=>{if(route.query.page)go({});else load()});onMounted(async()=>{await warehouses.fetchWarehouses();load()});onBeforeUnmount(()=>generation++)
useHead({title:()=>t('inventory-analysis.title')})
</script>
<template><div class="w-analysis w-scope"><header><div><h1>{{t('inventory-analysis.title')}}</h1><p>{{t('inventory-analysis.asof')}} {{data?.metric_date||'—'}}</p></div><div class="exports"><WButton v-for="format in (['csv','xlsx'] as const)" :key="format" icon="download" :disabled="loading||!ready||!data?.metric_date||exporting" @click="download(format)">{{t('goods.ui.export')}} {{format==='csv'?'CSV':'Excel'}}</WButton></div></header><div v-if="warehouseId&&ready" class="filters"><StockMetadataFilter v-for="field in (['category','brand'] as const)" :key="field" analysis :dimension="field" :warehouse-id="warehouseId" :filters="productScope" @change="value=>go(value)"/></div><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WCard v-if="!warehouseId"><WEmptyState :title="t('warehouse-scope.select-top')"/></WCard><WCard v-else-if="loading&&!data"><WEmptyState :title="t('common.status.loading')"/></WCard><WAlert v-else-if="data&&!data.metric_date" tone="info" :title="t('inventory-analysis.no-snapshot')"/><InventoryComposition :filters="productScope" v-if="warehouseId&&ready" :warehouse-id="warehouseId"/><InventoryStockTrend :filters="productScope" v-if="warehouseId&&ready" :warehouse-id="warehouseId"/><InventoryCapacity :filters="productScope" v-if="warehouseId&&ready" :warehouse-id="warehouseId"/><InventoryThresholds :filters="productScope" v-if="warehouseId&&ready" :warehouse-id="warehouseId"/><InventoryExpiry :filters="productScope" v-if="warehouseId&&ready" :warehouse-id="warehouseId"/><template v-if="data?.metric_date"><div class="metrics"><WCard v-for="item in [{key:'sku_with_stock',label:'stocked'},{key:'moving_sku',label:'moving'},{key:'dead_sku',label:'dead'},{key:'moving_rate',label:'moving-rate'}]" :key="item.key"><span>{{t('inventory-analysis.'+item.label)}}</span><strong>{{item.key==='moving_rate'?(summary[item.key]==null?'—':(summary[item.key]*100).toFixed(1)+'%'):summary[item.key]}}</strong></WCard></div><p class="scope-note">{{t('inventory-analysis.scope')}}</p><InventoryAge :summary="summary" @select="value=>go({age_bucket:value})"/><InventoryAbc :summary="summary" @select="value=>go({abc:value})"/></template><WCard v-if="warehouseId" flush><div class="table-head"><h2>{{t('inventory-analysis.goods')}}</h2><div class="filters"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('ledger.search')" @change="go({keyword:keyword.trim()})" @keydown.enter.prevent="go({keyword:keyword.trim()})"/><WFilterSelect :model-value="String(route.query.sort||'')||null" :options="sortOptions" :label="t('inventory-analysis.sort')" @change="value=>go({sort:value})"/><WFilterSelect :model-value="String(route.query.status||'')||null" :options="['normal','dead','empty'].map(value=>({value,label:t('inventory-analysis.'+value)}))" :label="t('common.fields.status')" @change="value=>go({status:value})"/><WFilterSelect :model-value="String(route.query.age_bucket||'')||null" :options="buckets.map(row=>({value:row.key,label:row.label}))" :label="t('inventory-analysis.age')" @change="value=>go({age_bucket:value})"/><WFilterSelect :model-value="String(route.query.abc||'')||null" :options="['A','B','C'].map(value=>({value,label:value}))" label="ABC" @change="value=>go({abc:value})"/></div></div><WTable :rows="data?.items||[]" :columns="columns" row-key="goods_id" :loading="loading" inset><template #cell-goods="{row}"><NuxtLink v-if="ready&&staff.hasPermission('goods_read')" class="w-analysis-link" :to="'/goods/detail/'+row.goods_id">{{row.goods?.name}}</NuxtLink><span v-else class="w-analysis-link">{{row.goods?.name}}</span><small>{{row.goods?.code}}</small></template><template #cell-status="{row}"><WStatus :tone="row.status==='dead'?'warn':'none'">{{t('inventory-analysis.'+row.status)}}</WStatus></template></WTable><footer><WPagination :page="Number(route.query.page)||1" :page-size="50" :total="data?.total" show-total @update:page="value=>go({page:value},true)"/></footer></WCard></div></template>
<style scoped>
.w-analysis{display:flex;flex-direction:column;gap:16px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}header>.w-select{width:240px}.exports{display:flex;gap:8px;flex-wrap:wrap}h1{margin:0;font-size:24px;line-height:32px;font-weight:600}h2{margin:0;font-size:16px;line-height:24px;font-weight:600}header p,.hint,.scope-note{font-size:12px;line-height:18px;color:var(--w-text-3);margin:8px 0 0}.scope-note{margin:0}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.metrics span{font-size:12px;line-height:18px;font-weight:500;color:var(--w-text-2)}.metrics strong{display:block;font-size:20px;line-height:28px;font-weight:600;margin-top:2px}h2 small{margin-left:12px;font-size:13px;font-weight:400;color:var(--w-text-2)}.age-chart{display:flex;flex-direction:column;gap:4px;margin:12px 0}.age-chart>div{display:grid;grid-template-columns:96px minmax(0,1fr) 160px;gap:12px;align-items:center;font-size:13px;line-height:20px;padding:6px 0}.age-value{color:var(--w-text-2);white-space:nowrap}.age-chart b{color:var(--w-text-1);font-weight:600}.track{height:20px}.track i{display:block;height:100%;border-radius:0 4px 4px 0}.abc-grid{display:grid;grid-template-columns:minmax(0,3fr) minmax(180px,1fr);gap:32px;margin-top:20px}.abc-grid svg{width:100%;max-height:280px}.abc-grid text{font-family:var(--w-font);font-size:12px;fill:#656C7A}.abc-values{display:flex;flex-direction:column;justify-content:center}.abc-values>div{display:flex;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--w-line);font-size:13px}.abc-values strong{margin-left:auto;font-weight:500}.table-head{padding:16px 20px;display:flex;flex-direction:column;gap:12px;border-bottom:1px solid var(--w-line)}.filters{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.filters>.w-input{width:360px}.filters>.w-select{width:140px}.w-analysis :deep(.w-table){min-width:1100px}.w-analysis :deep(td){padding-top:12px;padding-bottom:12px}.w-analysis-link{color:var(--w-text-1);font-size:14px;font-weight:500;text-decoration:none}td small{display:block;font-size:12px;color:var(--w-text-3)}footer{padding:12px 20px;border-top:1px solid var(--w-line)}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.abc-grid{grid-template-columns:minmax(0,1fr)}}@media(max-width:600px){header{align-items:stretch;flex-direction:column}header>.w-select{width:100%}.filters{flex-wrap:wrap}.filters>.w-input{width:100%}.age-chart>div{grid-template-columns:70px minmax(0,1fr) 115px}.metrics{gap:12px}}
</style>
